NAME = "frontload-sharpen"

def score(env, state, region_mask):
    # H1/H2: profits are temporarily inflated on days 1-2 (positive early bump /
    # mean-reverting high-initial nodes). Cash in on the top of the profit
    # distribution NOW by sharpening the ranking early; later, flatten it so the
    # greedy router keeps covering fresh mid-profit nodes instead of stalling.
    p = state.profit
    t = float(np.atleast_1d(state.t)[0])
    if t <= 2.0:
        temp = 0.55
        return p ** temp * (1.0 + 0.25 * (p > np.mean(p, axis=1, keepdims=True)))
    if t <= 4.0:
        temp = 0.8
    else:
        temp = 1.0 + 0.02 * t  # mild flattening late, counteracting log-drift
    boosted = p ** temp
    # tiny tie-break toward high-initial-profit POIs (H1 mean-reverts them up,
    # H2's decayed bump leaves them on a higher plateau)
    return boosted + 0.01 * (env.initial_profit[None, :] - 0.5)
